21→          const data = await res.json();
22→          if (typeof data.maxTotalSizeBytes === 'number') {
23→            setMaxTotalSizeBytes(data.maxTotalSizeBytes);
24→          }
25→        }
26→      } catch {
27→        // Config fetch is non-critical; use default
28→      }
29→    })();
30→  }, []);
31→
