259→  const [loading, setLoading] = useState(true);
260→  const [error, setError] = useState<string | null>(null);
261→  const [langfuseStatus, setLangfuseStatus] = useState<LangfuseStatus>({ enabled: false, dashboardUrl: null });
262→
263→  const refreshTables = useCallback(async () => {
264→    try {
265→      const response = await fetch('/api/tables');
266→      if (!response.ok) throw new Error('Failed to fetch tables');
267→      const data = await response.json();
268→      setTables(data);
269→    } catch (e) {
270→      console.error('Failed to refresh tables:', e);
271→    }
272→  }, []);
273→
274→  useEffect(() => {
275→    (async () => {
276→      try {
277→        const response = await fetch('/api/health');
278→        if (!response.ok) throw new Error('Backend is not available');
279→        await refreshTables();
280→        try {
281→          const lfRes = await fetch('/api/langfuse/status');
282→          if (lfRes.ok) {
283→            setLangfuseStatus(await lfRes.json());
284→          }
285→        } catch {
286→          // Langfuse status fetch is non-critical
287→        }
288→      } catch (e) {
289→        setError(e instanceof Error ? e.message : 'Failed to connect to backend');
290→      } finally {
291→        setLoading(false);
292→      }
293→    })();
294→  }, [refreshTables]);
295→
296→  if (loading) {
297→    return <div className="app-loading">Connecting to backend...</div>;
298→  }
299→
300→  if (error) {
301→    return (
302→      <div className="app-error">Failed to connect: {error}</div>
303→    );
304→  }
305→
306→  return (
307→    <ConfigProvider>
308→      <LanguageProvider>
309→        <ThemeProvider>
310→          <AgentProvider refreshTables={refreshTables}>
311→            <AppContent tables={tables} refreshTables={refreshTables} langfuseStatus={langfuseStatus} />
312→          </AgentProvider>
313→        </ThemeProvider>
314→      </LanguageProvider>
315→    </ConfigProvider>
316→  );
317→}
